// Дата: из ?date=ГГГГ-ММ-ДД при ручном перезапуске, иначе вчера по Москве.
const q = $json.query || {};
const forDate = q.date || $now.setZone('Europe/Moscow').minus({ days: 1 }).toFormat('yyyy-MM-dd');
if (!/^\d{4}-\d{2}-\d{2}$/.test(forDate) || !DateTime.fromISO(forDate).isValid) {
  throw new Error(`Неверная дата «${forDate}», нужен формат 2026-10-26`);
}
if (forDate >= $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd')) {
  throw new Error(`День ${forDate} ещё не закончился — грузим только закрытые дни`);
}
const parkId = $env.FLEET_PARK_ID || 'test-park';
const from = forDate + 'T00:00:00+03:00';
const to = DateTime.fromISO(forDate).plus({ days: 1 }).toFormat('yyyy-MM-dd') + 'T00:00:00+03:00';
return [{ json: {
  run_id: String($execution.id),
  for_date: forDate,
  park_id: parkId,
  client_id: $env.FLEET_CLIENT_ID || 'taxi/park/' + parkId,
  body: { query: { park: { id: parkId, transaction: { event_at: { from, to } } } }, limit: 100 },
} }];

// Все страницы ответа → одна пачка строк. Плохие строки откладываем с причиной, а не роняем запуск.
const p = $('Журнал: старт').first().json;
const rows = [];
const rejected = [];
for (const page of $input.all()) {
  if (!Array.isArray(page.json.transactions)) {
    throw new Error('Fleet API: ответ без transactions — ' + JSON.stringify(page.json).slice(0, 200));
  }
  for (const t of page.json.transactions) {
    const amount = Number(t.amount);
    let reason = null;
    if (!t.id) reason = 'нет id';
    else if (!t.driver_profile_id) reason = 'нет водителя';
    else if (!Number.isFinite(amount)) reason = `сумма «${t.amount}» не число`;
    if (reason) rejected.push({ txn_id: t.id ?? null, reason, raw: t });
    else rows.push({ txn_id: t.id, driver_id: t.driver_profile_id, event_at: t.event_at,
                     category: t.category_id, amount });
  }
}
// Повтор страницы при сбое пагинации даёт дубли — оставляем по одному на id.
const uniq = [...new Map(rows.map((r) => [r.txn_id, r])).values()];
if (!uniq.length && !rejected.length) {
  throw new Error(`Fleet API вернул 0 транзакций за ${p.for_date}: проверьте ключ и парк. База не тронута.`);
}
return [{ json: { run_id: p.run_id, for_date: p.for_date, fetched: rows.length + rejected.length, dupes: rows.length - uniq.length,
                  rows: JSON.stringify(uniq), rejected_rows: JSON.stringify(rejected) } }];

const u = $('Запись в PostgreSQL').first().json;
const p = u;
const d = $input.all().map((i) => i.json);
const total = d.reduce((s, r) => s + Number(r.total), 0);
const unchanged = Number(u.valid) - Number(u.inserted) - Number(u.updated);
const fmt = (n) => Number(n).toLocaleString('ru-RU', { maximumFractionDigits: 2 });
const text = [
  `Сверка за ${p.for_date}: ${p.fetched} транзакций, ${fmt(total)} ₽`,
  `новых ${u.inserted}, изменилось ${u.updated}, без изменений ${unchanged}`,
  Number(u.rejected) ? `⚠️ отложено ${u.rejected} (смотреть fleet_txn_rejected, run ${p.run_id})` : 'отложенных нет',
  'Топ-3 водителя: ' + d.slice(0, 3).map((r) => `${r.driver_id} — ${fmt(r.total)} ₽`).join('; '),
].join('\n');
return [{ json: { text, for_date: p.for_date, run_id: p.run_id, fetched: p.fetched, total,
                  inserted: Number(u.inserted), updated: Number(u.updated), rejected: Number(u.rejected) } }];
